const r = $json;
const dayMs = 24 * 3600e3;
const recent = [r.last_contact_at, r.last_inbound_at].filter(Boolean).some(t => Date.now() - new Date(t).getTime() < dayMs);
return { json: { ...r, send: !recent && r.status !== 'STOPPED' } };

function fill(t, vars) { return t.replace(/\{(\w+)\}/g, (m, k) => (vars[k] ?? m)); }
function buildOpenAI(model, system, userObj, maxTokens) {
  const req = {
    model,
    messages: [
      { role: 'system', content: system },
      { role: 'user', content: typeof userObj === 'string' ? userObj : JSON.stringify(userObj) }
    ],
    response_format: { type: 'json_object' },
    max_completion_tokens: maxTokens || 1500
  };
  // GPT-5 family / o-series are reasoning models: keep reasoning light for chat latency
  if (/^(gpt-5|o\d)/.test(model)) req.reasoning_effort = 'low';
  return req;
}
const P = "Write a concise, professional follow-up SMS for a roofing customer of {company} who received a quote.\nDo not: invent pricing, mention or change the quoted price, pressure the customer, or claim a deadline.\nAsk whether they have questions or want to proceed. Max 240 characters. No emojis.\nReturn JSON only: {\"reply\": \"message text\"}";

const r = $json;
const user = { customer_first_name: (r.name || '').split(' ')[0] || null, roofing_issue: r.problem_type,
               followup_number: r.quote_followups + 1, company: r.org_name };
return { json: { openai_request: buildOpenAI(r.settings?.ai?.models?.followup || 'gpt-5.4-mini', fill(P, { company: r.org_name }), user, 800) } };

const r = $json;
const content = r.choices?.[0]?.message?.content || '';
let parsed = null, parse_error = null;
try { parsed = JSON.parse(content); } catch (e) {
  const m = content.match(/\{[\s\S]*\}/);
  if (m) { try { parsed = JSON.parse(m[0]); } catch (e2) { parse_error = e2.message; } } else parse_error = e.message;
}
return { json: { parsed, parse_error, raw: content } };

const q = $('CHECK_LAST_CONTACT').item.json;
let reply = typeof $json.parsed?.reply === 'string' ? $json.parsed.reply.trim() : '';
const bad = !reply || reply.length > 320 || /\$\s?\d|\d+\s?(dollars|usd)|\b(expires?|deadline|only today|last chance)\b/i.test(reply);
const first = (q.name || '').split(' ')[0];
if (bad) reply = `Hi${first ? ' ' + first : ''}, it's ${q.org_name} — just checking whether you had any questions about your roofing quote, or if you'd like to go ahead. Happy to help either way.`;
return { json: { lead_id: q.lead_id, deal_id: q.deal_id, channel: 'sms', body: reply, kind: 'QUOTE_FOLLOWUP', ai_generated: !bad } };
